+import fs from "fs";
+import path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

 const store = new Map<string, Entry>();
+const STORAGE_FILE = path.join(process.cwd(), ".session-store.json");
+
+const loadFromDisk = (): void => {
+  try {
+    if (fs.existsSync(STORAGE_FILE)) {
+      const data = fs.readFileSync(STORAGE_FILE, "utf-8");
+      const entries = JSON.parse(data) as Record<string, Entry>;
+      const now = Date.now();
+      for (const [key, entry] of Object.entries(entries)) {
+        if (entry.expiresAt > now) {
+          store.set(key, entry);
+        }
+      }
+    }
+  } catch (error) {
+    console.error("Failed to load session store from disk:", error);
+  }
+};
+
+const saveToDisk = (): void => {
+  try {
+    const entries: Record<string, Entry> = {};
+    for (const [key, entry] of store.entries()) {
+      entries[key] = entry;
+    }
+    fs.writeFileSync(STORAGE_FILE, JSON.stringify(entries));
+  } catch (error) {
+    console.error("Failed to save session store to disk:", error);
+  }
+};
+
+loadFromDisk();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveToDisk();
 };

